from pathlib import Path

app_dir = Path(__file__).parent
main = app_dir / 'main.py'
s = main.read_text()

# Add a lightweight MQTT/add-on status endpoint before the device list endpoint.
anchor = "@app.get('/api/devices')\ndef devices():return list(DEVICES.values())"
replacement = """@app.get('/api/mqtt/status')
def mqtt_status():
 return {'connected': bool(MQTT and MQTT.is_connected()), 'device_count': len(DEVICES), 'devices': sorted(DEVICES.keys())}
@app.get('/api/devices')
def devices():return list(DEVICES.values())"""
if anchor not in s:
    raise SystemExit('Device list endpoint not found')
s = s.replace(anchor, replacement, 1)

# Replace only the hardware test page. The rest of the established 0.6.3 workflow stays untouched.
start = s.index('def hardware_page(project):')
end = s.index("@app.get('/usb/{project}'", start)
new_page = r'''def hardware_page(project):
 return """<!doctype html><html lang='de'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><script type='module' src='https://unpkg.com/esp-web-tools@10/dist/web/install-button.js?module'></script><style>body{font-family:system-ui;margin:20px;background:#111827;color:#e5e7eb}.card{background:#1f2937;padding:16px;border-radius:14px;margin:12px 0}button,select{padding:8px;margin:3px}pre{background:#030712;padding:12px;min-height:180px;white-space:pre-wrap}a{color:#93c5fd}.ok{color:#86efac}.warn{color:#fbbf24}.bad{color:#fca5a5}</style></head><body><h1>USB & Status: PROJECT</h1><div class='card'><h2>USB-Erstinstallation</h2><div id='manifestState'>Prüfe Manifest ...</div><esp-web-install-button id='installer'></esp-web-install-button></div><div class='card'><h2>Serieller Monitor</h2><button id='connectButton' onclick='connectSerial()'>Verbinden</button><button id='disconnectButton' onclick='disconnectSerial()' disabled>Trennen</button><button onclick='document.getElementById("serialLog").textContent=""'>Leeren</button><span id='serialState'>Nicht verbunden</span><pre id='serialLog'></pre></div><div class='card'><h2>WLAN</h2><p>Nach dem Flash mit <b>ESPManager-PROJECT</b> verbinden. Falls nötig 192.168.4.1 öffnen.</p></div><div class='card'><h2>MQTT-Gerätestatus</h2><div id='mqttConnection'>Prüfe Add-on-MQTT ...</div><label>Gerät: <select id='deviceSelect' onchange='selectDevice()'><option value=''>Noch kein Gerät gewählt</option></select></label><button onclick='refreshDevices()'>Geräteliste aktualisieren</button><p class='warn'>Das Projekt versucht zuerst das Gerät mit der ID <b>PROJECT</b> auszuwählen. Falls ein anderes Gerät meldet, kann es hier gewählt werden.</p><pre id='deviceStatus'>Noch kein MQTT-Status</pre></div><a href='../..'>Zurück</a><script>let port=null,reader=null,readLoopPromise=null,keepReading=false,selectedDevice='PROJECT';const decoder=new TextDecoder();const usbMarker='/usb/';function appBase(){const i=location.pathname.indexOf(usbMarker);if(i<0)throw Error('Ingress-Basispfad konnte nicht ermittelt werden');return location.pathname.slice(0,i+1)}function apiUrl(path){return appBase()+path.replace(/^\//,'')}async function checkManifest(){try{let base=location.pathname.endsWith('/')?location.pathname:location.pathname+'/';let url=base+'manifest.json';document.getElementById('installer').setAttribute('manifest',url);let r=await fetch(url,{cache:'no-store'});if(!r.ok)throw Error(await r.text());let m=await r.json();document.getElementById('manifestState').className='ok';document.getElementById('manifestState').textContent='Bereit: '+m.name+' '+m.version+' / '+m.builds[0].chipFamily}catch(e){document.getElementById('manifestState').className='bad';document.getElementById('manifestState').textContent='Manifest-Fehler: '+e.message}}async function readSerial(){try{while(keepReading&&port&&port.readable){reader=port.readable.getReader();try{while(keepReading){const result=await reader.read();if(result.done)break;if(result.value){const el=document.getElementById('serialLog');el.textContent+=decoder.decode(result.value,{stream:true});el.scrollTop=el.scrollHeight}}}finally{try{reader.releaseLock()}catch(e){}reader=null}}}catch(e){if(keepReading)document.getElementById('serialLog').textContent+='\\nLesefehler: '+e.message}}async function connectSerial(){if(port)return;try{port=await navigator.serial.requestPort();await port.open({baudRate:115200});keepReading=true;document.getElementById('serialState').textContent='Verbunden';document.getElementById('connectButton').disabled=true;document.getElementById('disconnectButton').disabled=false;readLoopPromise=readSerial()}catch(e){port=null;document.getElementById('serialState').textContent='Fehler: '+e.message}}async function disconnectSerial(){if(!port)return;keepReading=false;document.getElementById('disconnectButton').disabled=true;try{if(reader)await reader.cancel();if(readLoopPromise)await readLoopPromise;await port.close();document.getElementById('serialState').textContent='Getrennt'}catch(e){document.getElementById('serialState').textContent='Trennfehler: '+e.message}finally{reader=null;readLoopPromise=null;port=null;document.getElementById('connectButton').disabled=false}}async function refreshDevices(){try{const mqttResponse=await fetch(apiUrl('api/mqtt/status'),{cache:'no-store'});if(!mqttResponse.ok)throw Error(await mqttResponse.text());const mqtt=await mqttResponse.json();const mqttEl=document.getElementById('mqttConnection');mqttEl.className=mqtt.connected?'ok':'bad';mqttEl.textContent=mqtt.connected?'ESP Manager ist mit MQTT verbunden. Erkannte Geräte: '+mqtt.device_count:'ESP Manager ist nicht mit MQTT verbunden.';const r=await fetch(apiUrl('api/devices'),{cache:'no-store'});if(!r.ok)throw Error(await r.text());const devices=await r.json();const select=document.getElementById('deviceSelect');const old=selectedDevice;select.innerHTML='<option value="">Gerät auswählen</option>'+devices.map(d=>'<option value="'+d.device_id+'">'+d.device_id+(d.ip?' - '+d.ip:'')+'</option>').join('');if(devices.some(d=>d.device_id===old)){select.value=old}else if(devices.length===1){selectedDevice=devices[0].device_id;select.value=selectedDevice}else{select.value=''}await refreshSelectedDevice()}catch(e){document.getElementById('mqttConnection').className='bad';document.getElementById('mqttConnection').textContent='MQTT/API-Fehler: '+e.message;document.getElementById('deviceStatus').textContent='Keine Statusdaten verfügbar.'}}function selectDevice(){selectedDevice=document.getElementById('deviceSelect').value;refreshSelectedDevice()}async function refreshSelectedDevice(){if(!selectedDevice){document.getElementById('deviceStatus').textContent='Bitte ein erkanntes Gerät auswählen.';return}try{const r=await fetch(apiUrl('api/devices/'+encodeURIComponent(selectedDevice)),{cache:'no-store'});if(!r.ok)throw Error(await r.text());document.getElementById('deviceStatus').textContent=JSON.stringify(await r.json(),null,2)}catch(e){document.getElementById('deviceStatus').textContent='Für '+selectedDevice+' liegt noch kein Status vor: '+e.message}}checkManifest();refreshDevices();setInterval(refreshDevices,5000)</script></body></html>""".replace('PROJECT',clean(project))
'''
s = s[:start] + new_page + s[end:]
s = s.replace('ESP Manager Dev 0.6.3-dev','ESP Manager Dev 0.6.4-dev').replace('ESP Manager 0.6.3','ESP Manager 0.6.4')
main.write_text(s)
